//Imports all programs from a selected directory.
//@category Import




using ghidra.app.script;
using ghidra.app.util.importer;
using ghidra.app.util.importer;
using ghidra.app.util.opinion;
using ghidra.framework.model;
using ghidra.program.model.lang;
using ghidra.program.model.listing;

public class ImportAllProgramsFromADirectoryScript : GhidraScript {

	/* @Override */
	public void run()
    {
		File directory = askDirectory("Please specify the input directory:", "DIRECTORY");

		LanguageCompilerSpecPair language = askLanguage("Please select a language:", "LANGUAGE");

		DomainFolder folder = askProjectFolder("Please select a project folder:");

		MessageLog log = new MessageLog();

		File[] files = directory.listFiles();

		foreach (File file in files) {

			Thread.sleep(1000);

			if (monitor.isCancelled()) {
				break;
			}

			if (file.getName().startsWith(".")) {//skip private files... like ".svn"
				continue;
			}

			try
{
    using (LoadResults<Program> loadResults = ProgramLoader.builder()
					.source(file)
					.project(state.getProject())
					.projectFolderPath(folder.getPathname())
					.language(language.getLanguage())
					.compiler(language.getCompilerSpec())
					.log(log)
					.monitor(monitor)
					.load())
    {

				loadResults.getPrimary().save(monitor);
			
    }
}
			catch (IOException e) {
				println("Unable to import program from file " + file.getName());
			}

			println(log.toString());
			log.clear();
		}
	}
}
